-- 035_nutrition.sql — Onglet Nutrition de la refonte de Shaï (novembre 2026).
-- Uniquement des ajouts : la version déjà publiée continue de fonctionner.

-- Nombre de personnes d'une recette (stepper de la fiche et de « Ta recette »).
-- null = une portion (les recettes BBY sont saisies pour une personne).
alter table public.recipes
  add column if not exists servings smallint check (servings is null or servings between 1 and 20);

-- Base d'aliments de « Noter mon repas » : valeurs par portion, noms dans les 5 langues.
-- portion_g = poids de la portion ; piece_g = poids d'une pièce (pour calculer les
-- macros d'une recette perso saisie « 2 citrons »).
create table if not exists public.food_items (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  name_key text not null unique,
  category text not null default 'autre',
  portion_label text not null,
  portion_type text not null default 'g',
  portion_count numeric not null default 1,
  portion_g numeric not null,
  piece_g numeric,
  protein_g numeric not null default 0,
  fat_g numeric not null default 0,
  carb_g numeric not null default 0,
  kcal integer not null default 0,
  i18n jsonb not null default '{}'::jsonb,
  barcode text unique,
  created_at timestamptz not null default now()
);
alter table public.food_items enable row level security;
-- Catalogue commun en lecture seule pour les comptes connectés ; écriture réservée à l'admin.
drop policy if exists food_items_read on public.food_items;
create policy food_items_read on public.food_items
  for select to authenticated using (true);
drop policy if exists food_items_admin_write on public.food_items;
create policy food_items_admin_write on public.food_items
  for all using (public.is_admin()) with check (public.is_admin());

-- Photo d'une recette perso : chaque cliente écrit seulement dans recipe-media/user/<son id>/.
drop policy if exists recipe_media_user_insert on storage.objects;
create policy recipe_media_user_insert on storage.objects
  for insert to authenticated
  with check (bucket_id = 'recipe-media' and (storage.foldername(name))[1] = 'user'
              and (storage.foldername(name))[2] = auth.uid()::text);
drop policy if exists recipe_media_user_update on storage.objects;
create policy recipe_media_user_update on storage.objects
  for update to authenticated
  using (bucket_id = 'recipe-media' and (storage.foldername(name))[1] = 'user'
         and (storage.foldername(name))[2] = auth.uid()::text);
drop policy if exists recipe_media_user_delete on storage.objects;
create policy recipe_media_user_delete on storage.objects
  for delete to authenticated
  using (bucket_id = 'recipe-media' and (storage.foldername(name))[1] = 'user'
         and (storage.foldername(name))[2] = auth.uid()::text);

-- Aliments (générés, valeurs réalistes par portion)
on conflict (name_key) do nothing;
